from docx import Document

def compila(doc, valori):
    fatte = 0
    for p in doc.paragraphs:
        for run in p.runs:
            for chiave, valore in valori.items():
                segnaposto = "{{" + chiave + "}}"
                fatte += run.text.count(segnaposto)
                run.text = run.text.replace(segnaposto, str(valore))
    return fatte

doc = Document()
doc.add_paragraph("Lotto {{LOTTO}}, {{N}} pezzi")
print(compila(doc, {"LOTTO": "2026-118", "N": 48}), doc.paragraphs[0].text)
